import { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';

const BlogDetails = () => {
  const { id } = useParams();
  const [blog, setBlog] = useState(null);
  const [comment, setComment] = useState('');

  useEffect(() => {
    const fetchBlog = async () => {
      const res = await axios.get(`http://localhost:8080/api/blogs/${id}`);
      setBlog(res.data);
    };
    fetchBlog();
  }, [id]);

  const handleComment = async () => {
    await axios.post(`http://localhost:8080/api/blogs/${id}/comments`, comment);
    setBlog({ ...blog, comments: [...blog.comments, comment] });
    setComment('');
  };

  if (!blog) return <p>Loading...</p>;

  return (
    <div>
      <h1 className="text-2xl font-bold">{blog.title}</h1>
      <p>{blog.content}</p>
      <h3 className="font-bold">Comments:</h3>
      <ul>
        {blog.comments.map((c, index) => <li key={index}>{c}</li>)}
      </ul>
      <input type="text" value={comment} onChange={(e) => setComment(e.target.value)} placeholder="Add comment" />
      <button onClick={handleComment} className="bg-blue-500 text-white p-2">Comment</button>
    </div>
  );
};

export default BlogDetails;
